window.TIMELINE = {
 "voice": "narrator: ElevenLabs George (JBFqnCBsd6RMkjVDRZzb), cael: ElevenLabs Harry (SOYHLrjzK2X1ezoPC6cr), voice: ElevenLabs Lily (pFZP5JQG7iQjIQuC4Bku) [eleven_v4] (narrator tempo 1.06)",
 "set": "final",
 "total": 336.081,
 "scenes": [
  {
   "n": 0,
   "name": "The Name They Buried",
   "start": 0,
   "end": 14.219,
   "lines": [
    {
     "id": "C00",
     "speaker": "cael",
     "text": "They told me I was born without a name. I wasn't. They buried it.",
     "start": 2.6,
     "end": 7.479
    }
   ],
   "title": [
    7.619,
    13.819
   ]
  },
  {
   "n": 1,
   "name": "The Broken Seal",
   "start": 14.219,
   "end": 79.087,
   "lines": [
    {
     "id": "L01",
     "speaker": "narrator",
     "text": "You know how the Crown broke, and how the Seven took its throne.",
     "start": 16.619,
     "end": 20.389
    },
    {
     "id": "L02",
     "speaker": "narrator",
     "text": "This is the part the chronicles left out.",
     "start": 20.729,
     "end": 22.977
    },
    {
     "id": "L03",
     "speaker": "narrator",
     "text": "In the twelfth year, Lord Oswyn of Stanhyrst held the High Seat, and set out to break the laws that called some blood lesser.",
     "start": 23.317,
     "end": 31.323
    },
    {
     "id": "L04",
     "speaker": "narrator",
     "text": "",
     "start": 31.663,
     "end": 31.663,
     "cut": true
    },
    {
     "id": "L05",
     "speaker": "narrator",
     "text": "Six houses sealed his reform. House Sorn, keepers of the First-Born, did not.",
     "start": 31.663,
     "end": 37.455
    },
    {
     "id": "L06",
     "speaker": "narrator",
     "text": "On the night before the vote, the bells of the northern rookery began to ring.",
     "start": 37.795,
     "end": 41.983
    },
    {
     "id": "L07",
     "speaker": "narrator",
     "text": "A First-Born fell upon the capital. And the whole city looked up.",
     "start": 42.883,
     "end": 47.026
    },
    {
     "id": "L08",
     "speaker": "narrator",
     "text": "No one was watching the council chamber, where Oswyn's own captain put a knife in his back.",
     "start": 47.826,
     "end": 53.02
    },
    {
     "id": "L09",
     "speaker": "narrator",
     "text": "By dawn, the histories were written. A reckless lord. A rookery disaster. A wife and an infant son among the dead.",
     "start": 53.92,
     "end": 62.241
    },
    {
     "id": "L09a",
     "speaker": "narrator",
     "text": "But they had murdered a sworn lord at his own council table, and the land drank his blood. From that night, Aethelgard was cursed. The Seven never knew it.",
     "start": 62.841,
     "end": 73.191
    },
    {
     "id": "L10",
     "speaker": "narrator",
     "text": "And one witness lived. She was carrying the son.",
     "start": 74.091,
     "end": 77.547
    }
   ]
  },
  {
   "n": 2,
   "name": "The Unsworn",
   "start": 79.087,
   "end": 127.481,
   "lines": [
    {
     "id": "L11",
     "speaker": "narrator",
     "text": "Her name was Sive. Fenfolk. A nursemaid sworn to no house, and owed nothing by any law.",
     "start": 80.487,
     "end": 87.822
    },
    {
     "id": "L12",
     "speaker": "narrator",
     "text": "She carried the heir of Stanhyrst through the burning streets, wrapped in a servant's wool.",
     "start": 88.162,
     "end": 93.388
    },
    {
     "id": "L13",
     "speaker": "narrator",
     "text": "At the lower gate, a guard lifted the blanket. Then he looked at the swords coming down the stairs, and opened the gate.",
     "start": 93.728,
     "end": 100.834
    },
    {
     "id": "L14",
     "speaker": "narrator",
     "text": "They killed him for it.",
     "start": 101.434,
     "end": 102.676
    },
    {
     "id": "L15",
     "speaker": "narrator",
     "text": "Four nights north, where the roads give out beneath the fells, stood a poor hold named Ealdholt.",
     "start": 103.676,
     "end": 109.461
    },
    {
     "id": "L16",
     "speaker": "narrator",
     "text": "Its elder, Edda, asked the child's name. Sive said only: one that will get him killed.",
     "start": 109.801,
     "end": 116.908
    },
    {
     "id": "L17",
     "speaker": "narrator",
     "text": "So Edda gave him her father's. Cael. And in the register, beside his parentage, she wrote one word. Unknown.",
     "start": 117.608,
     "end": 125.741
    }
   ]
  },
  {
   "n": 3,
   "name": "A Son of Ealdholt",
   "start": 127.481,
   "end": 159.512,
   "lines": [
    {
     "id": "L18",
     "speaker": "narrator",
     "text": "Twenty-one winters. The heir to the High Seat grew up mending spears, guarding a ford, and waiting outside the doors of greater men.",
     "start": 130.081,
     "end": 138.893
    },
    {
     "id": "L19",
     "speaker": "narrator",
     "text": "His blood did not make him strong. He practised until his hands bled, and learned to read a man before the man knew his own mind.",
     "start": 139.233,
     "end": 147.168
    },
    {
     "id": "L20",
     "speaker": "narrator",
     "text": "Runa, the healer's girl, warned him once. They don't need to beat you, Cael. They only need to decide you may not stand.",
     "start": 147.508,
     "end": 155.481
    },
    {
     "id": "L21",
     "speaker": "narrator",
     "text": "He did not believe her. Not yet.",
     "start": 155.821,
     "end": 158.172
    }
   ]
  },
  {
   "n": 4,
   "name": "The Ford",
   "start": 159.512,
   "end": 184.269,
   "lines": [
    {
     "id": "L22",
     "speaker": "narrator",
     "text": "When House Hildmere claimed Ealdholt's ford, the law said: settle it on the board.",
     "start": 161.112,
     "end": 166.178
    },
    {
     "id": "L23",
     "speaker": "narrator",
     "text": "Cael stood as a Pawn. He gave ground. He let them believe the open file was a mistake.",
     "start": 166.518,
     "end": 172.518
    },
    {
     "id": "L24",
     "speaker": "narrator",
     "text": "And when their champion came through it, he closed the door.",
     "start": 173.118,
     "end": 176.274
    },
    {
     "id": "L25",
     "speaker": "narrator",
     "text": "Ealdholt kept its road. And for once, its banner was spoken of in the south.",
     "start": 177.074,
     "end": 181.929
    }
   ]
  },
  {
   "n": 5,
   "name": "The Muster",
   "start": 184.269,
   "end": 223.174,
   "lines": [
    {
     "id": "L26",
     "speaker": "narrator",
     "text": "At the National Muster, the born took the great pieces, as they always do. Cael took the front rank.",
     "start": 185.869,
     "end": 192.252
    },
    {
     "id": "L27",
     "speaker": "narrator",
     "text": "",
     "start": 192.592,
     "end": 192.592,
     "cut": true
    },
    {
     "id": "L28",
     "speaker": "narrator",
     "text": "The clerk read his papers twice. Ward of Ealdholt. Parentage, unknown.",
     "start": 192.592,
     "end": 198.309
    },
    {
     "id": "L29",
     "speaker": "narrator",
     "text": "In the final trial, Cael reached the last rank. Every gallery waited for him to choose the Queen.",
     "start": 199.109,
     "end": 205.297
    },
    {
     "id": "L30",
     "speaker": "narrator",
     "text": "He chose the Knight. It struck the king and the queen in one move, and the game was over.",
     "start": 205.997,
     "end": 211.517
    },
    {
     "id": "L31",
     "speaker": "narrator",
     "text": "They knighted him for it. A silver star, on a pawn's cloak.",
     "start": 212.217,
     "end": 216.216
    },
    {
     "id": "L32",
     "speaker": "narrator",
     "text": "And in the high gallery, a hooded man asked for every record of the twelfth year.",
     "start": 216.556,
     "end": 221.234
    }
   ]
  },
  {
   "n": 6,
   "name": "The Road Home",
   "start": 223.174,
   "end": 259.855,
   "lines": [
    {
     "id": "L33",
     "speaker": "narrator",
     "text": "Cael would not wait in the capital. He wanted Edda to see the star.",
     "start": 224.774,
     "end": 228.933
    },
    {
     "id": "L34",
     "speaker": "narrator",
     "text": "He bought her a clasp shaped like an oak leaf. Nothing royal. Just something she would like.",
     "start": 229.273,
     "end": 234.824
    },
    {
     "id": "L35",
     "speaker": "narrator",
     "text": "On the north road, a cart lay overturned. No driver. No horse. Then the arrows.",
     "start": 235.724,
     "end": 242.269
    },
    {
     "id": "L36",
     "speaker": "narrator",
     "text": "The men who came out of the trees wore no colours. They had not come for silver.",
     "start": 243.069,
     "end": 247.86
    },
    {
     "id": "L37",
     "speaker": "narrator",
     "text": "They tore his name from the Muster record. And so that no grave would ever be found, they built a fire, and laid him on an iron grate above it.",
     "start": 248.2,
     "end": 256.939
    },
    {
     "id": "L38",
     "speaker": "narrator",
     "text": "He did not beg.",
     "start": 257.839,
     "end": 258.915
    }
   ]
  },
  {
   "n": 7,
   "name": "The Fire",
   "start": 259.855,
   "end": 301.822,
   "lines": [
    {
     "id": "C01",
     "speaker": "cael",
     "text": "No board. No arbiter. Faces hidden. Is this how the Seven fight?",
     "start": 261.255,
     "end": 267.331
    },
    {
     "id": "C02",
     "speaker": "cael",
     "text": "Turn me over, cowards. This side is done.",
     "start": 268.231,
     "end": 273.317
    },
    {
     "id": "C03",
     "speaker": "cael",
     "text": "Burn the name. Burn the boy. I will come back for both.",
     "start": 274.317,
     "end": 278.625
    },
    {
     "id": "L39",
     "speaker": "narrator",
     "text": "They fed the fire until the laughing stopped.",
     "start": 280.025,
     "end": 282.746
    },
    {
     "id": "L40",
     "speaker": "narrator",
     "text": "Twice now, the kingdom had buried his name. This time, it buried him.",
     "start": 283.946,
     "end": 288.655
    },
    {
     "id": "L41",
     "speaker": "narrator",
     "text": "But twenty-one years before, at a council table, the Seven had cursed their own kingdom. In Aethelgard, the dead do not rest.",
     "start": 290.055,
     "end": 298.482
    }
   ]
  },
  {
   "n": 8,
   "name": "The Unreturned",
   "start": 301.822,
   "end": 324.881,
   "lines": [
    {
     "id": "V01",
     "speaker": "voice",
     "text": "You remember.",
     "start": 305.222,
     "end": 306.097
    },
    {
     "id": "C04",
     "speaker": "cael",
     "text": "The fire. I remember the fire.",
     "start": 307.297,
     "end": 310.141
    },
    {
     "id": "V02",
     "speaker": "voice",
     "text": "Then you remember dying. Most do not.",
     "start": 311.141,
     "end": 314.74
    },
    {
     "id": "V03",
     "speaker": "voice",
     "text": "This is the Wyrdmark, where the curse keeps its dead. And now and then, it lets one walk back.",
     "start": 315.74,
     "end": 322.941
    }
   ]
  }
 ],
 "chapter": [
  324.481,
  335.481
 ]
};
